import Foundation

// MARK: - ActionProposal
/// Represents a strictly typed, untrusted proposal generated by an LLM.
/// This model must pass trusted policy validation and human approval before execution.
public struct ActionProposal: Codable, Sendable, Equatable {
    public let type: String
    public let scenarioID: String
    public let snapshotID: String
    public let elementID: String
    public let expectedRole: String
    public let expectedIdentifier: String?
    public let toolName: String
    public let arguments: [String: AnyCodableValue]
    public let reason: String
    public let stepIndex: Int?
    public let stepID: String?

    public init(
        type: String = "action_proposal",
        scenarioID: String,
        snapshotID: String,
        elementID: String,
        expectedRole: String,
        expectedIdentifier: String? = nil,
        toolName: String,
        arguments: [String: AnyCodableValue] = [:],
        reason: String,
        stepIndex: Int? = nil,
        stepID: String? = nil
    ) {
        self.type = type
        self.scenarioID = scenarioID
        self.snapshotID = snapshotID
        self.elementID = elementID
        self.expectedRole = expectedRole
        self.expectedIdentifier = expectedIdentifier
        self.toolName = toolName
        self.arguments = arguments
        self.reason = reason
        self.stepIndex = stepIndex
        self.stepID = stepID
    }

    enum CodingKeys: String, CodingKey {
        case type
        case scenarioID
        case snapshotID
        case elementID
        case expectedRole
        case expectedIdentifier
        case toolName
        case arguments
        case reason
        case stepIndex
        case stepID
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.type = try container.decodeIfPresent(String.self, forKey: .type) ?? "action_proposal"
        self.scenarioID = try container.decode(String.self, forKey: .scenarioID)
        self.snapshotID = try container.decode(String.self, forKey: .snapshotID)
        self.elementID = try container.decode(String.self, forKey: .elementID)
        self.expectedRole = try container.decode(String.self, forKey: .expectedRole)
        self.expectedIdentifier = try container.decodeIfPresent(String.self, forKey: .expectedIdentifier)
        self.toolName = try container.decode(String.self, forKey: .toolName)
        self.arguments = try container.decodeIfPresent([String: AnyCodableValue].self, forKey: .arguments) ?? [:]
        self.reason = try container.decode(String.self, forKey: .reason)
        self.stepIndex = try container.decodeIfPresent(Int.self, forKey: .stepIndex)
        self.stepID = try container.decodeIfPresent(String.self, forKey: .stepID)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(type, forKey: .type)
        try container.encode(scenarioID, forKey: .scenarioID)
        try container.encode(snapshotID, forKey: .snapshotID)
        try container.encode(elementID, forKey: .elementID)
        try container.encode(expectedRole, forKey: .expectedRole)
        try container.encodeIfPresent(expectedIdentifier, forKey: .expectedIdentifier)
        try container.encode(toolName, forKey: .toolName)
        try container.encode(arguments, forKey: .arguments)
        try container.encode(reason, forKey: .reason)
        try container.encodeIfPresent(stepIndex, forKey: .stepIndex)
        try container.encodeIfPresent(stepID, forKey: .stepID)
    }
}
